custom_qss:
/* ============================================================
   INTERFERENCE — clashing axes by design, in new colors. Every
   surface runs its gradient on a different angle (window wide
   diagonal, dialog steeper, menus reversed, toolbars/docks
   vertical) so the UI reads as deliberately "off". Violet/magenta
   base, warm amber + cool mint accents. Static's weirdness, new hues.
   ============================================================ */

* {
    border: none;
    background-color: transparent !important;
    color: #ece2f5 !important;
}
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent !important;
    border: none;
}

/* window: long diagonal violet drift */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0.7, y2:0.5,
        stop:0 #2a1140, stop:0.3 #1f0d33, stop:0.55 #170a26,
        stop:0.8 #2b1440, stop:1 #120819) !important;
}
QDialog {
    background: qlineargradient(x1:0.3, y1:0, x2:0.9, y2:1,
        stop:0 #2a1140, stop:0.4 #1c0d2e, stop:1 #120819) !important;
    border-top: 2px solid #f5b83e;
}

/* menubar: flat strip */
QMenuBar { background: #150a24 !important; border-bottom: 1px solid #3a1f57; }
QMenuBar::item {
    padding: 5px 12px; border-radius: 4px;
    background: transparent !important; color: #9a7ab8 !important;
}
QMenuBar::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #f5b83e, stop:0.7 #3a1f57) !important;
    color: #ffffff !important;
}

/* popup: OPPOSITE diagonal to window */
QMenu {
    background: qlineargradient(x1:1, y1:0, x2:0.2, y2:1,
        stop:0 #33164d, stop:0.6 #1c0d2e, stop:1 #241238) !important;
    border: 1px solid #4a2a6b; border-radius: 7px; padding: 6px;
}
QMenu::item {
    padding: 6px 24px 6px 14px; border-radius: 4px;
    background: transparent !important; color: #ece2f5 !important;
}
QMenu::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #7ee8c0, stop:0.55 #2e8f6b, stop:1 #3a1f57) !important;
    color: #120819 !important; font-weight: 600;
}
QMenu::item:disabled { color: #5a4070 !important; }
QMenu::separator {
    height: 2px;
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #f5b83e, stop:1 #3a1f57) !important;
    margin: 6px 8px;
}

/* toolbar: vertical, clashing with the diagonal window */
QToolBar {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #2e1548, stop:1 #150a24) !important;
    border-bottom: 1px solid #3a1f57; spacing: 3px; padding: 4px;
}
QToolBar::separator { background: #4a2a6b; width: 2px; margin: 6px 4px; }
QToolBar QToolButton {
    background: transparent !important; padding: 5px 8px; border-radius: 4px;
    color: #9a7ab8 !important; font-size: 12px;
}
QToolBar QToolButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #7ee8c0, stop:1 #2e8f6b) !important; color: #120819 !important;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #f5b83e, stop:1 #ffd98a) !important; color: #120819 !important;
}

/* buttons: steep skewed arc, amber sheen */
QPushButton {
    background: qlineargradient(x1:0, y1:0, x2:0.85, y2:1,
        stop:0 #3d1a5c, stop:0.4 #2e1548, stop:0.75 #331a4d,
        stop:0.9 #402060, stop:1 #150a24) !important;
    border-radius: 6px; padding: 6px 18px;
    color: #ece2f5 !important; font-weight: 600; font-size: 12px;
}
QPushButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0.85, y2:1,
        stop:0 #7ee8c0, stop:0.5 #2e8f6b, stop:1 #1c5a44) !important;
    color: #120819 !important;
}
QPushButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:0.85, y2:1,
        stop:0 #ffd98a, stop:0.5 #f5b83e, stop:1 #a87a1e) !important;
    color: #120819 !important; padding: 7px 17px 5px 19px;
}
QPushButton:checked {
    background: qlineargradient(x1:0, y1:0, x2:0.85, y2:1,
        stop:0 #f5b83e, stop:0.6 #3a1f57, stop:1 #150a24) !important;
    color: #ffd98a !important;
}
QPushButton:default { border-left: 3px solid #7ee8c0; }
QPushButton:disabled { background: #150a24 !important; color: #5a4070 !important; }

/* inputs: flat dark wells, mint focus */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background-color: #0f0719 !important;
    border: 1px solid #3a1f57; border-left: 3px solid #3a1f57; border-radius: 4px;
    padding: 5px 8px; color: #7ee8c0 !important; font-size: 12px;
    selection-background-color: #3a1f57; selection-color: #7ee8c0;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    border-left: 3px solid #7ee8c0; background-color: #170a26 !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled { color: #5a4070 !important; }
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent !important; border: none; width: 16px;
}

QComboBox {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0.4,
        stop:0 #2e1548, stop:1 #331a4d) !important;
    border: 1px solid #3a1f57; border-left: 3px solid #3a1f57; border-radius: 4px;
    padding: 5px 8px; color: #ece2f5 !important; font-size: 12px;
}
QComboBox:hover { border-left: 3px solid #f5b83e; }
QComboBox:focus { border-left: 3px solid #7ee8c0; }
QComboBox::drop-down { border: none; background: transparent !important; width: 18px; }
QComboBox QAbstractItemView {
    background: #1c0d2e !important; border: 1px solid #4a2a6b; border-radius: 6px;
    padding: 4px; selection-background-color: #3a1f57; selection-color: #7ee8c0;
}
QComboBox:disabled { color: #5a4070 !important; }

/* checkboxes: mint-checked */
QCheckBox, QRadioButton { color: #ece2f5 !important; background: transparent !important; padding: 3px; }
QCheckBox::indicator, QRadioButton::indicator {
    width: 15px; height: 15px; background: #0f0719 !important;
    border: 1px solid #4a2a6b; border-radius: 3px;
}
QRadioButton::indicator { border-radius: 8px; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover { border: 1px solid #7ee8c0; }
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1, stop:0 #7ee8c0, stop:1 #2e8f6b) !important;
    border: 1px solid #7ee8c0;
}

/* tabs: mixed-axis pills, amber-to-mint selected */
QTabBar { background: transparent !important; }
QTabBar::tab {
    background: transparent !important; color: #9a7ab8 !important;
    padding: 7px 16px; border-radius: 4px; margin: 0 1px;
}
QTabBar::tab:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #3a1f57, stop:1 #150a24) !important;
    color: #7ee8c0 !important;
}
QTabBar::tab:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #3a1f57, stop:0.5 #4a2a6b, stop:1 #f5b83e) !important;
    color: #ffffff !important; font-weight: 600;
}
QTabWidget::pane { border: 1px solid #3a1f57; background: #150a24 !important; }

/* docks: vertical sweep + amber clash edge */
QDockWidget {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #33164d, stop:0.6 #1c0d2e, stop:1 #2b1440) !important;
    border: 1px solid #3a1f57;
}
QDockWidget::title {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #3a1f57, stop:0.75 #2e1548, stop:1 #f5b83e) !important;
    border-bottom: 2px solid #f5b83e; padding: 7px 10px;
    color: #ffffff !important; font-weight: 700;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent !important; border: none; padding: 2px; border-radius: 3px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover { background: #f5b83e !important; }

/* group boxes */
QGroupBox {
    background: transparent !important; border: 1px solid #3a1f57;
    border-left: 3px solid #4a2a6b; border-radius: 5px; margin-top: 14px; padding-top: 8px;
    font-weight: 600; color: #ece2f5 !important;
}
QGroupBox::title {
    subcontrol-origin: margin; subcontrol-position: top left; padding: 0 7px;
    background: #150a24 !important; color: #7ee8c0 !important;
}

/* item views */
QAbstractItemView {
    background: #0f0719 !important; border: 1px solid #3a1f57; border-radius: 5px;
    alternate-background-color: #170a26;
    selection-background-color: #3a1f57; selection-color: #7ee8c0; outline: none;
}
QAbstractItemView::item { padding: 4px; }
QAbstractItemView::item:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #2e1548, stop:1 #3a1f57) !important;
}
QAbstractItemView::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #3a1f57, stop:1 #4a2a6b) !important;
    border-left: 3px solid #7ee8c0; color: #7ee8c0 !important;
}
QAbstractItemView::item:selected:!active { background: #241238 !important; border-left: 3px solid #3a1f57; color: #ece2f5 !important; }
QTreeView::branch { background: transparent !important; }

QHeaderView::section {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1, stop:0 #331a4d, stop:1 #150a24) !important;
    border: none; border-bottom: 2px solid #f5b83e; padding: 6px 8px;
    color: #ffd98a !important; font-weight: 600;
}

/* scrollbars: mint handles */
QScrollBar:vertical { background: #0f0719 !important; width: 12px; margin: 0; }
QScrollBar::handle:vertical {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #7ee8c0, stop:0.5 #2e8f6b, stop:1 #3a1f57) !important;
    border-radius: 3px; min-height: 28px;
}
QScrollBar::handle:vertical:hover { background: #f5b83e !important; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; background: none; border: none; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: #0f0719 !important; }
QScrollBar:horizontal { background: #0f0719 !important; height: 12px; margin: 0; }
QScrollBar::handle:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #7ee8c0, stop:0.5 #2e8f6b, stop:1 #3a1f57) !important;
    border-radius: 3px; min-width: 28px;
}
QScrollBar::handle:horizontal:hover { background: #f5b83e !important; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0; background: none; border: none; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: #0f0719 !important; }
QScrollBar::corner { background: #0f0719 !important; }

/* sliders: amber-to-mint sweep */
QSlider::groove:horizontal { background: #0f0719 !important; border: 1px solid #3a1f57; height: 5px; border-radius: 2px; }
QSlider::sub-page:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #f5b83e, stop:0.5 #7ee8c0, stop:1 #2e8f6b) !important;
    border-radius: 2px;
}
QSlider::handle:horizontal { background: #7ee8c0 !important; width: 12px; margin: -5px 0; border-radius: 6px; }
QSlider::handle:horizontal:hover { background: #f5b83e !important; }

/* progress: full clash bar */
QProgressBar {
    background: #0f0719 !important; border: 1px solid #3a1f57; border-radius: 5px;
    text-align: center; color: #ece2f5 !important; min-height: 15px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #f5b83e, stop:0.35 #7ee8c0, stop:0.65 #2e8f6b, stop:0.85 #3a1f57, stop:1 #7ee8c0) !important;
}

/* statusbar */
QStatusBar {
    background: qlineargradient(x1:1, y1:0, x2:0, y2:0, stop:0 #2e1548, stop:1 #150a24) !important;
    border-top: 2px solid #7ee8c0; color: #9a7ab8 !important;
}

/* tooltip */
QToolTip { background: #1c0d2e !important; border: 1px solid #7ee8c0; border-radius: 5px; padding: 6px 9px; color: #7ee8c0 !important; }

/* splitters */
QSplitter::handle { background: #3a1f57 !important; }
QSplitter::handle:hover { background: #7ee8c0 !important; }
